def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Any diagonal segment of equal-valued cells is extended at either end
    # through the background color 9. Zero is also a valid line color.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 9:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    for y, x, sy, sx in (
                        (r - dr, c - dc, -dr, -dc),
                        (rr + dr, cc + dc, dr, dc),
                    ):
                        while 0 <= y < h and 0 <= x < w and grid[y][x] == 9:
                            out[y][x] = color
                            y += sy
                            x += sx
    return out

